function Search({ allRows }: { allRows: Row[] }) {
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  // expensive: filters 12k rows
  const filtered = allRows.filter((r) =>
    r.name.toLowerCase().includes(deferredQuery.toLowerCase()),
  );

  return (
    <>
      <input value={deferredQuery} onChange={(e) => setQuery(e.target.value)} />
      <ResultsGrid rows={filtered} />
    </>
  );
}

// not memoized
function ResultsGrid({ rows }: { rows: Row[] }) {
  return (
    <table>
      {rows.map((r) => (
        <Row key={r.id} row={r} />
      ))}
    </table>
  );
}
